#!/usr/bin/env node
// Builds synthetic, disposable sourcemap-lineage test fixtures. No private repo, no
// third-party source, no network access. Every file, commit and build here is
// generated by this script; nothing is copied from any other project.
//
// Output layout (default: fixtures/generated/, gitignored, safe to delete/rerun):
//   generated/repo/          synthetic git repo (own .git, isolated from the parent repo)
//   generated/artifacts/*/   esbuild bundles + .map files for each labeled case
//
// Determinism: fixed author/committer identity and timestamps are used for every
// commit so the resulting blobs, commit hashes and artifact bytes are reproducible
// across machines. If esbuild ever changes its output for the same inputs, the
// pinned hashes in regression.test.cjs will fail loudly rather than silently drift.
'use strict';
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const HERE = __dirname;
const OUT = process.argv[2] ? path.resolve(process.argv[2]) : path.join(HERE, 'generated');
const REPO = path.join(OUT, 'repo');
const ARTIFACTS = path.join(OUT, 'artifacts');

const TOOLING = path.join(HERE, '..', 'tooling');
let esbuildApi;
try { esbuildApi = require(path.join(TOOLING, 'node_modules', 'esbuild')); }
catch { console.error(`esbuild not found. Run: npm install --prefix "${TOOLING}"`); process.exit(1); }

// Fixed, arbitrary timestamps (2020-01-01T00:00:00Z onward, one minute apart). Not
// real dates; chosen only so every generated commit is byte-identical across runs.
const BASE_T = 1577836800; // 2020-01-01T00:00:00Z
let tCounter = 0;
function nextDate() { return new Date((BASE_T + (tCounter++) * 60) * 1000).toISOString(); }

function rimraf(p) { fs.rmSync(p, { recursive: true, force: true }); }
function mkdirp(p) { fs.mkdirSync(p, { recursive: true }); }
function writeFile(p, content) { mkdirp(path.dirname(p)); fs.writeFileSync(p, content); }

function gitEnv(dateIso) {
  return {
    ...process.env,
    GIT_AUTHOR_NAME: 'Fixture Bot', GIT_AUTHOR_EMAIL: 'fixture@example.invalid', GIT_AUTHOR_DATE: dateIso,
    GIT_COMMITTER_NAME: 'Fixture Bot', GIT_COMMITTER_EMAIL: 'fixture@example.invalid', GIT_COMMITTER_DATE: dateIso,
  };
}
function git(args, opts = {}) {
  return execFileSync('git', ['-c', 'user.name=Fixture Bot', '-c', 'user.email=fixture@example.invalid', '-C', REPO, ...args],
    { encoding: 'utf8', ...opts }).trim();
}
function commit(message, dateIso) {
  git(['add', '-A']);
  git(['commit', '-q', '--allow-empty', '-m', message], { env: gitEnv(dateIso) });
  return git(['rev-parse', 'HEAD']);
}

// ---------- synthetic source content ----------
// Plain, unminified, repetitive-but-distinct lines so map-evidence.cjs's whole-line
// context-anchor check (>=50 anchors, every mapped source represented) is satisfied
// without needing a large realistic codebase.
// Multi-line, one statement per line: esbuild's printer preserves this shape closely
// enough for map-evidence.cjs's whole-line context-anchor check to find matches.
// Numbers are kept inside string literals only (never bare numeric literals): esbuild's
// printer canonicalizes bare numbers (e.g. 1000 -> 1e3), which would silently break the
// verbatim whole-line match the anchor check requires.
function block(prefix, count, tag) {
  const lines = [];
  for (let i = 0; i < count; i++) {
    const id = `${prefix}${String(i).padStart(3, '0')}`;
    lines.push(`export function ${id}(x) {`);
    lines.push(`  return applyFixtureTransform(x, "${id}", "${tag}");`);
    lines.push(`}`);
  }
  return lines.join('\n') + '\n';
}
const ALPHA_V1 = block('alpha', 60, 'v1');
const BETA_V1 = block('beta', 60, 'v1');
const ALPHA_V2 = ALPHA_V1.replace('"alpha000", "v1"', '"alpha000", "v2-feature-edit"'); // small, real feature edit
const BETA_V2 = block('beta', 60, 'v1').replace('"beta000", "v1"', '"beta000", "v2-feature-edit"');
const INDEX_JS = [
  'import * as alpha from "./alpha.js";',
  'import * as beta from "./beta.js";',
  '',
  'export function fixtureIndexMarker() {',
  '  return applyFixtureTransform(0, "index000", "v1");',
  '}',
  '',
  'export function summarizeFixtureModules() {',
  '  return { alphaCount: Object.keys(alpha).length, betaCount: Object.keys(beta).length };',
  '}',
  '',
].join('\n');

function esbuild(entry, outfile) {
  mkdirp(path.dirname(outfile));
  esbuildApi.buildSync({
    entryPoints: [path.join(REPO, entry)], absWorkingDir: REPO, bundle: true, platform: 'node',
    format: 'esm', sourcemap: true, outfile, logLevel: 'error',
  });
}

// ---------- build the synthetic repo ----------
rimraf(OUT);
mkdirp(REPO);
git(['init', '-q', '-b', 'main']);
git(['config', 'core.autocrlf', 'false']);

writeFile(path.join(REPO, 'src/alpha.js'), ALPHA_V1);
writeFile(path.join(REPO, 'src/beta.js'), BETA_V1);
writeFile(path.join(REPO, 'src/index.js'), INDEX_JS);
writeFile(path.join(REPO, 'README.md'), '# fixture project\n\nSynthetic, generated by generate-fixtures.cjs. Not a real package.\n');
const initCommit = commit('init: synthetic fixture project', nextDate());

writeFile(path.join(REPO, 'src/alpha.js'), ALPHA_V2);
const cleanCommit = commit('feature: adjust alpha (clean baseline)', nextDate());

// Same src/ tree as cleanCommit, only an unrelated top-level file changes.
// Produces a second commit with identical tracked blobs -> candidate group of 2.
writeFile(path.join(REPO, 'README.md'), '# fixture project\n\nSynthetic, generated by generate-fixtures.cjs. Not a real package.\n\nUpdated wording only; no src/ change.\n');
const ambiguousCommit = commit('docs: reword README (src unchanged)', nextDate());

writeFile(path.join(REPO, 'src/alpha.js'), ALPHA_V2.replace('"alpha000", "v2-feature-edit"', '"alpha000", "v3-tip-edit"'));
writeFile(path.join(REPO, 'src/beta.js'), BETA_V2);
const tipCommit = commit('feature: adjust alpha and beta (tip)', nextDate());

console.log(`init=${initCommit}`);
console.log(`clean=${cleanCommit}`);
console.log(`ambiguous=${ambiguousCommit}`);
console.log(`tip=${tipCommit}`);

// ---------- A. clean: build at tipCommit, no other commit shares its exact src/ tree ----------
git(['checkout', '-q', tipCommit]);
esbuild('src/index.js', path.join(ARTIFACTS, 'A-clean', 'app.js'));

// ---------- B. dirty: build at tip, then append an uncommitted edit before building ----------
git(['checkout', '-q', tipCommit]);
fs.appendFileSync(path.join(REPO, 'src/beta.js'), '\n// uncommitted local debug helper, never committed\nexport function betaDebugOverride(x) { return x; }\n');
esbuild('src/index.js', path.join(ARTIFACTS, 'B-dirty', 'app.js'));
git(['checkout', '-q', '--', 'src/beta.js']); // discard the uncommitted edit in the fixture repo itself

// ---------- C. ambiguous group: build at ambiguousCommit, src/ tree identical to cleanCommit's ----------
git(['checkout', '-q', ambiguousCommit]);
esbuild('src/index.js', path.join(ARTIFACTS, 'C-ambiguous-group', 'app.js'));

// ---------- D. stale/incompatible map: C's artifact bytes (differently-shaped build) ----------
// paired with A-clean's map, whose sourcesContent alone would otherwise be a unique,
// single-commit EXACT match. This demonstrates the downgrade: artifactMap INCOMPATIBLE
// must not let a legacy EXACT_COMMIT_MATCH summary stand uncorroborated.
mkdirp(path.join(ARTIFACTS, 'D-stale-map'));
fs.copyFileSync(path.join(ARTIFACTS, 'C-ambiguous-group', 'app.js'), path.join(ARTIFACTS, 'D-stale-map', 'app.js'));
fs.copyFileSync(path.join(ARTIFACTS, 'A-clean', 'app.js.map'), path.join(ARTIFACTS, 'D-stale-map', 'app.js.map'));

// ---------- E. EOL-only: same as A-clean, but one recovered source's sourcesContent is CRLF ----------
mkdirp(path.join(ARTIFACTS, 'E-eol-only'));
fs.copyFileSync(path.join(ARTIFACTS, 'A-clean', 'app.js'), path.join(ARTIFACTS, 'E-eol-only', 'app.js'));
{
  const mapPath = path.join(ARTIFACTS, 'A-clean', 'app.js.map');
  const map = JSON.parse(fs.readFileSync(mapPath, 'utf8'));
  const idx = map.sources.findIndex((s) => s.endsWith('alpha.js'));
  if (idx < 0) throw new Error('alpha.js not found in map sources');
  map.sourcesContent[idx] = map.sourcesContent[idx].replace(/\n/g, '\r\n');
  fs.writeFileSync(path.join(ARTIFACTS, 'E-eol-only', 'app.js.map'), JSON.stringify(map));
}

git(['checkout', '-q', tipCommit]);
console.log('done');
